export type CloseReason = "member_left" | "balancer_timeout" | "auth_failed";

export interface Socket {
  id: string;
  lastSeenMs: number;
  token?: string;
}

export function upgradeAllowed(socket: Socket): boolean {
  return Boolean(socket.token);
}

export function scheduleNext(socket: Socket): number {
  return nextHeartbeatAt(socket.lastSeenMs);
}

export function closeReasonFor(socket: Socket, nowMs: number, idleBudgetMs: number): CloseReason {
  return nowMs - socket.lastSeenMs > idleBudgetMs ? "balancer_timeout" : "member_left";
}

