export class PresenceRegistry {
  private readonly online = new Map<string, number>();

  mark(memberId: string, atMs: number): void {
    this.online.set(memberId, atMs);
  }

  evictStale(nowMs: number, budgetMs: number): string[] {
    const dropped: string[] = [];
    for (const [memberId, seenAt] of this.online) {
      if (nowMs - seenAt > budgetMs) {
        this.online.delete(memberId);
        dropped.push(memberId);
      }
    }
    return dropped.sort();
  }

  members(): string[] {
    return [...this.online.keys()].sort();
  }
}

