const pending = new Set<string>();

export function queueChange(memberId: string): void {
  pending.add(memberId);
}

/** One frame per tick, however many changes a busy room produced. */
export function drainFrame(): string[] {
  const batch = [...pending].sort();
  pending.clear();
  return batch;
}

